import ghidra.app.decompiler.*; import ghidra.app.script.GhidraScript; import ghidra.program.model.listing.*; import ghidra.program.model.symbol.*;
public class ContactWriterCallers extends GhidraScript { public void run()throws Exception{DecompInterface d=new DecompInterface();d.openProgram(currentProgram);long[] xs={0x00425ef0L,0x00426620L,0x004d65f0L,0x004190d0L};for(long x:xs){Function t=getFunctionAt(toAddr(x));println("\nTARGET "+toAddr(x)+" "+t);for(Reference rr:getReferencesTo(t.getEntryPoint())){Function f=getFunctionContaining(rr.getFromAddress());if(f!=null)println("CALLER "+rr.getFromAddress()+" "+f.getName());}}d.dispose();}}
